from AlgorithmImports import *
from math import isfinite


class ChainedUniverseAlgorithm(QCAlgorithm):
    def initialize(self) -> None:
        self.set_start_date(2024, 9, 1)
        self.set_end_date(2024, 12, 31)
        self.set_cash(100000)
        self.settings.seed_initial_prices = True
        self.universe_settings.asynchronous = False
        self._weight_by_symbol: dict[Symbol, float] = {}
        self._qqq = self.add_equity("QQQ", Resolution.MINUTE).symbol
        self._universe = self.add_universe(
            self.universe.etf("QQQ", Market.USA, self.universe_settings, self._etf_filter),
            self._fundamental_filter
        )
        self.schedule.on(
            self.date_rules.every_day(self._qqq),
            self.time_rules.before_market_open(self._qqq, 30),
            self._place_orders
        )

    def _etf_filter(self, constituents: list[ETFConstituentUniverse]) -> list[Symbol]:
        self._weight_by_symbol = {}
        for constituent in constituents:
            weight = float(constituent.weight or 0.0)
            if isfinite(weight) and weight > 0:
                self._weight_by_symbol[constituent.symbol] = weight
        return list(self._weight_by_symbol)

    def _fundamental_filter(self, fundamentals: list[Fundamental]) -> list[Symbol]:
        ranked = []
        for fundamental in fundamentals:
            ratio = fundamental.valuation_ratios.pe_ratio
            if ratio is None or fundamental.symbol not in self._weight_by_symbol:
                continue
            ratio = float(ratio)
            # Zero represents an unavailable P/E; do not reject finite negative P/E implicitly.
            if isfinite(ratio) and ratio != 0:
                ranked.append((ratio, fundamental.symbol))
        ranked.sort(key=lambda item: item[0])
        return [symbol for _, symbol in ranked[:10]]

    def _place_orders(self) -> None:
        selected = [symbol for symbol in self._universe.selected if symbol in self._weight_by_symbol]
        total = sum(self._weight_by_symbol[symbol] for symbol in selected)
        if not selected or not isfinite(total) or total <= 0:
            self.liquidate()
            return
        targets = [PortfolioTarget(symbol, self._weight_by_symbol[symbol] / total) for symbol in selected]
        self.set_holdings(targets, liquidate_existing_holdings=True)
