from AlgorithmImports import *
from math import isfinite


class DualMomentumAlgorithm(QCAlgorithm):
    def initialize(self) -> None:
        self.set_start_date(2022, 1, 1)
        self.set_end_date(2024, 12, 31)
        self.set_cash(100000)
        self.settings.seed_initial_prices = True
        self.settings.automatic_indicator_warm_up = True
        self._momentum = {}
        for ticker in ["SPY", "EFA", "AGG"]:
            symbol = self.add_equity(ticker, Resolution.MINUTE).symbol
            self._momentum[symbol] = self.rocp(symbol, 252, resolution=Resolution.DAILY)
        self._spy = next(symbol for symbol in self._momentum if symbol.value == "SPY")
        self.schedule.on(
            self.date_rules.month_start(self._spy),
            self.time_rules.after_market_open(self._spy, 1),
            self._rebalance
        )

    def _rebalance(self) -> None:
        if self.is_warming_up or not all(indicator.is_ready for indicator in self._momentum.values()):
            return
        returns = {symbol: float(indicator.current.value) for symbol, indicator in self._momentum.items()}
        if not all(isfinite(value) for value in returns.values()):
            return
        if not all(self.securities[symbol].has_data and self.securities[symbol].price > 0 for symbol in self._momentum):
            return
        winner = max(returns, key=returns.get)
        self.set_holdings([PortfolioTarget(winner, 1.0)], liquidate_existing_holdings=True)
