        self._window = RollingWindow[TradeBar](20)

    def on_data(self, data: Slice) -> None:
        bar = data.bars.get(self._symbol)
        if bar is None:
            return
        self._window.add(bar)
        if not self._window.is_ready:
            return
        invested = self.portfolio[self._symbol].invested
        if self._window[0].close > self._window[1].close and not invested:
            self.set_holdings(self._symbol, 1.0)
        elif self._window[0].close < self._window[1].close and invested:
            self.liquidate(self._symbol)
