from AlgorithmImports import *


class WarmUpRollingWindowAlgorithm(QCAlgorithm):
    def initialize(self) -> None:
        self.set_start_date(2024, 9, 1)
        self.set_end_date(2024, 12, 31)
        self.set_cash(100000)
        self.settings.seed_initial_prices = True
        self._symbol = self.add_equity("SPY", Resolution.DAILY).symbol
        self._window = RollingWindow[TradeBar](20)
        self._last_end_time = None
        for bar in self.history[TradeBar](self._symbol, self._window.size, Resolution.DAILY):
            self._window.add(bar)
            self._last_end_time = bar.end_time

    def on_data(self, data: Slice) -> None:
        bar = data.bars.get(self._symbol)
        if bar is None:
            return
        if self._last_end_time is not None and bar.end_time <= self._last_end_time:
            return
        self._window.add(bar)
        self._last_end_time = bar.end_time
        if not self._window.is_ready:
            return
        invested = self.portfolio[self._symbol].invested
        if self._window[0].close > self._window[1].close and not invested:
            self.set_holdings(self._symbol, 1.0)
        elif self._window[0].close < self._window[1].close and invested:
            self.liquidate(self._symbol)
